### Browser Speech API Integration

The modular system uses a dedicated VoiceRecognition component for speech processing:

```javascript
// search-voice-recognition.js
class VoiceRecognition {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.recognition = new (window.SpeechRecognition || window.webkitSpeechRecognition)();
    this.isListening = false;
    this.wakeWords = ['aria', 'hey aria', 'hello aria'];
    this.setupRecognition();
  }

  setupRecognition() {
    this.recognition.continuous = true;
    this.recognition.interimResults = true;
    this.recognition.lang = 'en-US';
    this.recognition.maxAlternatives = 1;

    this.recognition.onresult = (event) => this.handleSpeechResult(event);
    this.recognition.onerror = (event) => this.handleSpeechError(event);
    this.recognition.onend = () => this.handleSpeechEnd();
  }

  handleSpeechResult(event) {
    const transcript = Array.from(event.results)
      .map((result) => result[0].transcript)
      .join('')
      .toLowerCase();

    if (this.detectWakeWord(transcript)) {
      this.orchestrator.onWakeWordDetected();
    } else if (this.orchestrator.isAwaitingCommand()) {
      this.orchestrator.onCommandReceived(transcript);
    }
  }

  detectWakeWord(transcript) {
    return this.wakeWords.some((wakeWord) => transcript.includes(wakeWord.toLowerCase()));
  }

  start() {
    if (!this.isListening) {
      this.recognition.start();
      this.isListening = true;
    }
  }

  stop() {
    if (this.isListening) {
      this.recognition.stop();
      this.isListening = false;
    }
  }
}

// Global reference for legacy compatibility
window.VoiceRecognition = VoiceRecognition;
```

