[.tooling/components/apps/mkdocs-platform/docs/speech_interface_design.md#audio-implementation]

### Audio Implementation

```javascript
// search-audio-manager.js
class AudioManager {
  constructor(orchestrator) {
    this.orchestrator = orchestrator;
    this.audioContext = null;
    this.speechSynthesis = window.speechSynthesis;
    this.volume = 0.1;
    this.voices = [];
    this.currentVoice = null;
    this.initializeAudio();
  }

  async initializeAudio() {
    try {
      this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      await this.loadVoices();
      this.selectBestVoice();
      this.orchestrator.onAudioReady();
    } catch (error) {
      this.orchestrator.onAudioError(error);
    }
  }

  loadVoices() {
    return new Promise((resolve) => {
      this.voices = this.speechSynthesis.getVoices();
      if (this.voices.length > 0) {
        resolve();
      } else {
        this.speechSynthesis.onvoiceschanged = () => {
          this.voices = this.speechSynthesis.getVoices();
          resolve();
        };
      }
    });
  }

  selectBestVoice() {
    const preferredVoices = [
      'Microsoft Aria Online (Natural) - English (United States)',
      'Google US English',
      'Alex',
    ];

    for (const preferred of preferredVoices) {
      const voice = this.voices.find((v) => v.name.includes(preferred));
      if (voice) {
        this.currentVoice = voice;
        return;
      }
    }

    this.currentVoice = this.voices.find((v) => v.lang.startsWith('en')) || this.voices[0];
  }

  playReadyBeep() {
    this.playFrequencySweep(400, 600, 0.15);
  }

  playSearchBeep() {
    const frequencies = [500, 650, 800];
    frequencies.forEach((freq, index) => {
      setTimeout(() => {
        this.playTone(freq, 0.1);
      }, index * 100);
    });
  }

  playTone(frequency, duration) {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();

    oscillator.frequency.setValueAtTime(frequency, this.audioContext.currentTime);
    gain.gain.setValueAtTime(this.volume, this.audioContext.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + duration);

    oscillator.connect(gain);
    gain.connect(this.audioContext.destination);

    oscillator.start(this.audioContext.currentTime);
    oscillator.stop(this.audioContext.currentTime + duration);
  }

  playFrequencySweep(startFreq, endFreq, duration) {
    if (!this.audioContext) return;

    const oscillator = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();

    oscillator.frequency.setValueAtTime(startFreq, this.audioContext.currentTime);
    oscillator.frequency.linearRampToValueAtTime(endFreq, this.audioContext.currentTime + duration);

    gain.gain.setValueAtTime(this.volume, this.audioContext.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, this.audioContext.currentTime + duration);

    oscillator.connect(gain);
    gain.connect(this.audioContext.destination);

    oscillator.start(this.audioContext.currentTime);
    oscillator.stop(this.audioContext.currentTime + duration);
  }

  speak(text, options = {}) {
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.voice = this.currentVoice;
    utterance.rate = options.rate || 1.0;
    utterance.pitch = options.pitch || 1.0;
    utterance.volume = options.volume || 0.8;

    return new Promise((resolve, reject) => {
      utterance.onend = resolve;
      utterance.onerror = reject;
      this.speechSynthesis.speak(utterance);
    });
  }
}

// Global reference for legacy compatibility
window.AudioManager = AudioManager;
```

